```python
class Database:
    def __init__(self):
        self.data = {}

    def add(self, key, value):
        """Add a new key-value pair to the database."""
        if key not in self.data:
            self.data[key] = value
            print(f"Data added successfully: {key} = {value}")
        else:
            print(f"Key '{key}' already exists in the database.")

    def remove(self, key):
        """Remove a key-value pair from the database."""
        if key in self.data:
            del self.data[key]
            print(f"Data removed successfully: {key}")
        else:
            print(f"Key '{key}' does not exist in the database.")

    def query(self, key):
        """Query the database for a value associated with a given key."""
        if key in self.data:
            return self.data[key]
        else:
            print(f"Key '{key}' does not exist in the database.")
            return None


# Example usage:
db = Database()

# Add data
db.add("name", "John Doe")
db.add("age", 30)
db.add("city", "New York")

# Remove data
db.remove("age")

# Query data
print(db.query("name"))  # Output: John Doe
print(db.query("job"))   # Output: Key 'job' does not exist in the database.
```

This implementation provides the specified functionality for adding, removing, and querying data in a simple database. You can extend this implementation to use a more complex data structure or a real database library like `sqlite3` or `pymongo` as needed.
